update term_entry set

    ${moidfyFieldName}= #{modifyFieldValueArray[${index}]}

where id in

    #{id}

mapper.select:
select t1.entry_id 'entryId',t1.text 'firstLangContent',t2.text 'secondLangContent' from ( SELECT tel.entry_id, tel.language_id,GROUP_CONCAT( DISTINCT ti.text ORDER BY ti.text SEPARATOR ';' ) 'text' ,max(te.created) 'create_time',max(te.field) 'field' from term_entry_lang tel left join term_entry te on te.id=tel.entry_id left join term_item ti on ti.term_entry_lang_id=tel.id where (tel.language_id=#{firstLang} and te.tb_guid=#{tbId}) and te.status='T' GROUP BY tel.entry_id, tel.language_id ) t1 left join ( SELECT tel.entry_id, tel.language_id,GROUP_CONCAT( DISTINCT ti.text ORDER BY ti.text SEPARATOR ';' ) 'text' from term_entry_lang tel left join term_entry te on te.id=tel.entry_id left join term_item ti on ti.term_entry_lang_id=tel.id where (tel.language_id=#{secondLang} and te.tb_guid=#{tbId}) and te.status='T' GROUP BY tel.entry_id, tel.language_id ) t2 on t1.entry_id=t2.entry_id where 1=1
and (t1.text like '%${keyword}%' or t2.text like '%${keyword}%')
and
FIND_IN_SET(#{field}, t1.field) != 0
and t1.create_time >= #{beginTime}
and t1.create_time < #{endTime}
